mapper.select:
SELECT * FROM ( SELECT DBMS_RANDOM.VALUE AS rand, idx, name, catename, catecode, address, areaname, areacode, tel, locationx, locationy, url, contents, etc, use_yn, img_url FROM CULTURE_INFO_TBL WHERE 1 = 1
AND areaname = #{search_area}
ORDER BY DBMS_RANDOM.VALUE ) WHERE ROWNUM <= 10

${pagingTop}
  SELECT
    idx, name, catename, catecode, address,
    areaname, areacode, tel, locationx, locationy,
    url, contents, etc, use_yn, img_url
  FROM
  CULTURE_INFO_TBL
  WHERE
    1 = 1

    AND	${search_type} LIKE '%'||#{search_text}||'%'


    AND catecode = #{search_cate}


    AND areacode = #{search_area}

${pagingBottom}

SELECT COUNT(*) FROM CULTURE_INFO_TBL WHERE 1 = 1
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND catecode = #{search_cate}
AND areacode = #{search_area}
